public static int[][] PickLots(int[][] lots, int today, int requested)
{
    var picks = new List<int[]>();
    foreach (var lot in lots.Where(lot => lot[1] >= today).OrderBy(lot => lot[1]).ThenBy(lot => lot[0]))
    {
        if (requested == 0)
            break;

        int quantity = Math.Min(requested, lot[2]);
        picks.Add([lot[0], quantity]);
        requested -= quantity;
    }

    return picks.ToArray();
}

