public static int[] OrderJobs(int count, int[][] dependencies)
{
    var after = new List<int>[count];
    var pending = new int[count];
    for (int job = 0; job < count; job++)
        after[job] = [];

    foreach (var pair in dependencies)
    {
        after[pair[0]].Add(pair[1]);
        pending[pair[1]]++;
    }

    var ready = new PriorityQueue<int, int>();
    for (int job = 0; job < count; job++)
        if (pending[job] == 0)
            ready.Enqueue(job, job);

    var order = new List<int>(count);
    while (ready.TryDequeue(out int job, out _))
    {
        order.Add(job);
        foreach (int next in after[job])
            if (--pending[next] == 0)
                ready.Enqueue(next, next);
    }

    return order.Count == count ? order.ToArray() : [];
}

