public static long CalculateCharge(int units, int[] limits, int[] rates)
{
    long charge = 0;
    int previous = 0;
    for (int tier = 0; tier < limits.Length && previous < units; tier++)
    {
        int billedThrough = Math.Min(units, limits[tier]);
        charge += (long)(billedThrough - previous) * rates[tier];
        previous = billedThrough;
    }

    return charge + (long)(units - previous) * rates[^1];
}

