public static int[] DaysUntilHigher(int[] stock)
{
    var days = new int[stock.Length];
    var candidates = new Stack<int>();
    for (int day = stock.Length - 1; day >= 0; day--)
    {
        while (candidates.TryPeek(out int next) && stock[next] <= stock[day])
            candidates.Pop();

        if (candidates.TryPeek(out int higher))
            days[day] = higher - day;
        candidates.Push(day);
    }

    return days;
}

