public static int PeakRooms(int[][] bookings)
{
    var starts = bookings.Select(slot => slot[0]).ToArray();
    var ends = bookings.Select(slot => slot[1]).ToArray();
    Array.Sort(starts);
    Array.Sort(ends);

    int departed = 0;
    int peak = 0;
    for (int arrived = 0; arrived < starts.Length; arrived++)
    {
        while (departed < ends.Length && ends[departed] <= starts[arrived])
            departed++;

        peak = Math.Max(peak, arrived + 1 - departed);
    }

    return peak;
}

